insert into legislative_propositions (external_id, house, proposition_type, number, year, title, summary, official_url) values ('camara-proposicao-2580259-plp', 'camara', 'plp', 230, 2025, 'PLP 230', 'Altera a Lei Complementar nº 101, de 4 de maio de 2000, para vedar a limitação de empenho e movimentação financeira das despesas relativas ao Fundo de Universalização dos Serviços de Telecomunicações, e a Lei nº 9.998, de 17 de agosto de 2000, para os fins que especifica.', 'https://dadosabertos.camara.leg.br/api/v2/proposicoes/2580259') on conflict (house, external_id) do update set proposition_type = 'plp', number = 230, year = 2025, title = 'PLP 230', summary = 'Altera a Lei Complementar nº 101, de 4 de maio de 2000, para vedar a limitação de empenho e movimentação financeira das despesas relativas ao Fundo de Universalização dos Serviços de Telecomunicações, e a Lei nº 9.998, de 17 de agosto de 2000, para os fins que especifica.', official_url = 'https://dadosabertos.camara.leg.br/api/v2/proposicoes/2580259';
insert into proposition_versions (proposition_id, version_key, version_label, text_hash, source_reference_id, effective_from) values ((select id from legislative_propositions where house = 'camara' and external_id = 'camara-proposicao-2580259-plp'), 'event-2580259-24', 'Aprovado o Substitutivo ao Projeto de Lei Complementar nº 230, de 2025, adotado pela relatora da Comissão de Finanças e Tributação. Sim: 333; Não: 91; Total: 424.', 'sha256:b989bd0e5bf93fe811299164aae3808305673d571831c84ba561bf2ad6abdcb9', 'cea888ca-65a1-484b-ba7b-438603a8f380', '2026-08-12T22:48:20.000Z') on conflict (proposition_id, version_key) do update set version_label = 'Aprovado o Substitutivo ao Projeto de Lei Complementar nº 230, de 2025, adotado pela relatora da Comissão de Finanças e Tributação. Sim: 333; Não: 91; Total: 424.', text_hash = 'sha256:b989bd0e5bf93fe811299164aae3808305673d571831c84ba561bf2ad6abdcb9', source_reference_id = 'cea888ca-65a1-484b-ba7b-438603a8f380', effective_from = '2026-08-12T22:48:20.000Z';
